<?php
use DigiForge\PortalAccess\{Feature,Owner,Store,Session,Panel};
require_once __DIR__.'/fixtures/PortalAccessFixture.php';
final class PortalManagementTest extends WP_UnitTestCase {
 protected function setUp():void{parent::setUp();PortalAccessFixture::reset();}
 protected function tearDown():void{global $wpdb;$wpdb->query('COMMIT');PortalAccessFixture::reset();$wpdb->query('COMMIT');$wpdb->query('START TRANSACTION');parent::tearDown();}
 public function testManagementRequiresNonceAndExplicitSignedOwner():void{PortalAccessFixture::owner();$f=new Feature();self::assertWPError($f->process('digiforge_portal_users',[]));self::assertStringContainsString('server-approved Global Primary Owner',Panel::render());$id=PortalAccessFixture::enroll();self::assertStringContainsString('Owner dashboard',Panel::render());}
 public function testRoleEscalationAndUnknownShopAreDenied():void{$owner=PortalAccessFixture::enroll();$id=self::factory()->user->create(['role'=>'administrator']);self::assertWPError(Store::change($id,'Primary Owner',['personalized_pod'=>['research']],true,0,wp_generate_uuid4()));self::assertWPError(Store::change($id,'Admin',['unknown'=>['research']],true,0,wp_generate_uuid4()));self::assertNull(Store::read($id));}
 public function testReenableDoesNotReviveOldSessionAndPreservesNativeWpSession():void{$owner=PortalAccessFixture::enroll();$id=self::factory()->user->create(['role'=>'administrator']);$s=Store::change($id,'Operator',['personalized_pod'=>['research']],true,0,wp_generate_uuid4());PortalAccessFixture::login($id);Session::start();$df=$_COOKIE[Session::name()];$wp=$_COOKIE[LOGGED_IN_COOKIE];$token=wp_get_session_token();PortalAccessFixture::login($owner);PortalAccessFixture::verifyEmail();Session::start();$s=Store::change($id,'Operator',['personalized_pod'=>['research']],false,$s['revision'],wp_generate_uuid4());$s=Store::change($id,'Operator',['personalized_pod'=>['research']],true,$s['revision'],wp_generate_uuid4());wp_set_current_user($id);$_COOKIE[LOGGED_IN_COOKIE]=$wp;$_COOKIE[Session::name()]=$df;self::assertFalse(Session::valid($s));self::assertTrue(WP_Session_Tokens::get_instance($id)->verify($token));self::assertTrue(is_user_logged_in());}
 public function testModuleRevocationAndStaleRevisionCannotAddAccess():void{PortalAccessFixture::enroll();$id=self::factory()->user->create(['role'=>'administrator']);$s=Store::change($id,'Viewer',['personalized_pod'=>['research']],true,0,wp_generate_uuid4());self::assertNotWPError($s);self::assertWPError(Store::change($id,'Admin',['personalized_pod'=>['settings']],true,0,wp_generate_uuid4()));$r=Store::change($id,'Viewer',['personalized_pod'=>[]],false,$s['revision'],wp_generate_uuid4());self::assertNotWPError($r);self::assertSame([],$r['shops']);PortalAccessFixture::login($id);self::assertWPError(Session::start());self::assertWPError(\DigiForge\Security\ShopAccess::authorize('personalized_pod','manage_digiforge'));}
 public function testManagementCannotMutatePrimaryOwnerOrWordPressCapabilities():void{$id=PortalAccessFixture::enroll();$before=get_userdata($id)->to_array();$s=Store::read($id);self::assertWPError(Store::change($id,'Viewer',['personalized_pod'=>['research']],false,$s['revision'],wp_generate_uuid4()));self::assertSame($before,get_userdata($id)->to_array());}
 public function testInvitationPageIsAvailableToPendingActorWithoutProtectedPortalContent():void{PortalAccessFixture::enroll();$id=self::factory()->user->create(['role'=>'administrator']);\DigiForge\PortalAccess\Invitations::create($id,'Viewer','personalized_pod',['research'],time()+60,wp_generate_uuid4());PortalAccessFixture::login($id);$_GET['df_view']='invitation';try{$html=(new Feature())->before(false,'digiforge_admin_portal',[],[]);self::assertStringContainsString('Accept DigiForge invitation',$html);self::assertStringNotContainsString('Owner dashboard',$html);}finally{$_GET=[];}}
}
